/* Автоклікер (Premium Pass): максимум половину доби активної роботи на
   добу (ліміт скидається щодня). Клікає раз на 200 мс (5 разів/сек) —
   тобто в моменти коли є "банк" накопиченої енергії (після офлайну чи
   паузи) він швидко спалює його, а не цідить по краплі. У довгостроковій
   перспективі середня швидкість все одно обмежена регенерацією енергії
   (+1/сек, максимум 100), як і в звичайних гравців — це баланс гри, не
   можна клікати швидше, ніж встигає відновлюватись енергія. */
const AUTO_CLICKER_TICK_MS = 200;
const AUTO_CLICKER_DAILY_LIMIT_MS = 12 * 60 * 60 * 1000;
/* Кулдаун між діями лідера/радника/повстанця (8 годин) */
const ACTION_COOLDOWN_MS = 8 * 60 * 60 * 1000;
export { cnSfx };

/* Автоклікер, поки гравець НЕ в грі: коли гра завантажується, рахуємо,
   скільки енергії "накопичилось" за час відсутності (регенерація вже
   рахується формулою getCurrentEnergy), і одразу конвертуємо цю енергію
   в Power/кліки — так, ніби автоклікер бив по глобусу весь цей час.
   Це не безкінечний фарм: банк енергії обмежений 100, тож офлайн-бонус
   за одне повернення в гру теж обмежений максимум ~100 кліками. */
function applyOfflineAutoClicker(rec) {
  if (!rec || !rec.hasPremiumPass || !rec.autoClickerOn) return rec;
  const todayKey = new Date().toISOString().slice(0, 10);
  const usedToday = rec.autoClickerDate === todayKey ? rec.autoClickerUsedMs || 0 : 0;
  const remainingBudgetMs = AUTO_CLICKER_DAILY_LIMIT_MS - usedToday;
  if (remainingBudgetMs <= 0) {
    return { ...rec, autoClickerOn: false };
  }
  const currentEnergy = getCurrentEnergy(rec);
  const budgetClicks = Math.floor(remainingBudgetMs / AUTO_CLICKER_TICK_MS);
  const clicksToApply = Math.max(0, Math.min(Math.floor(currentEnergy), budgetClicks));
  if (clicksToApply <= 0) return rec;
  const usedMs = usedToday + clicksToApply * AUTO_CLICKER_TICK_MS;
  return {
    ...rec,
    power: rec.power + clicksToApply,
    totalClicks: rec.totalClicks + clicksToApply,
    energy: currentEnergy - clicksToApply,
    lastEnergyTs: Date.now(),
    autoClickerDate: todayKey,
    autoClickerUsedMs: usedMs,
    autoClickerOn: usedMs < AUTO_CLICKER_DAILY_LIMIT_MS,
    __offlineCredited: clicksToApply > 0,
  };
}
