function ShopScreen({ onGoToSeason, me, onSetPlayer, isLeader, isAdvisor, onRefreshGameData }) {
  const [detailsOpen, setDetailsOpen] = useState(false);

  return (
    <div className="cn-shop">
      <div className="cn-shop-card">
        <img className="cn-shop-banner-img" src={SHOP_BANNER_IMG} alt="Premium Pass" />
        <button className="cn-shop-more-btn" type="button" onClick={() => { cnSfx.modalOpen(); setDetailsOpen(true); }}>
          Дізнатися більше
          <ChevronRight size={16} />
        </button>
      </div>

      <RolesShopSection me={me} onSetPlayer={onSetPlayer} isLeader={isLeader} isAdvisor={isAdvisor} onRefreshGameData={onRefreshGameData} />

      <div className="cn-control-wip">
        <ShoppingBag size={20} />
        <div>Магазин наповнюється товарами — незабаром тут з'являться нові пропозиції.</div>
      </div>

      {detailsOpen && (
        <PremiumPassModal onClose={() => setDetailsOpen(false)} me={me} onSetPlayer={onSetPlayer} onGoToSeason={onGoToSeason} />
      )}
    </div>
  );
}

/* Влада: купівля ролей Лідер / Радник / Повстанець за ROLE_PRICE Power. */
function RolesShopSection({ me, onSetPlayer, isLeader, isAdvisor, onRefreshGameData }) {
  const [advisorsCount, setAdvisorsCount] = useState(null);
  const [busyRole, setBusyRole] = useState(null);
  const [msg, setMsg] = useState("");

  const refreshAdvisorsCount = useCallback(async () => {
    if (!me) return;
    const list = await getAdvisors(me.countryCode);
    setAdvisorsCount(list.length);
  }, [me]);

  useEffect(() => {
    refreshAdvisorsCount();
  }, [refreshAdvisorsCount]);

  if (!me) return null;

  const canAfford = (me.power || 0) >= ROLE_PRICE;
  const advisorsFull = advisorsCount !== null && advisorsCount >= MAX_ADVISORS;

  const buy = async (role) => {
    setBusyRole(role);
    setMsg("");
    const res = await buyCountryRole(me, role, onSetPlayer);
    if (res.ok) {
      cnSfx.purchase();
      setMsg("✓ Роль придбано!");
      await refreshAdvisorsCount();
      if (onRefreshGameData) await onRefreshGameData();
    } else {
      cnSfx.error();
      setMsg("✗ " + res.reason);
    }
    setBusyRole(null);
  };

  const roles = [
    {
      id: "leader",
      label: "Лідер",
      icon: Crown,
      desc: "Одноосібно керує країною: оголошує війни, укладає союзи, виганяє радників.",
      disabled: isLeader,
      disabledReason: isLeader ? "Ти вже лідер" : "У країні вже є лідер",
    },
    {
      id: "advisor",
      label: "Радник",
      icon: UserCog,
      desc: `Місце в Раді (до ${MAX_ADVISORS} радників). Разом рада може голосувати за війну, союз чи усунення лідера.`,
      disabled: isLeader || isAdvisor || advisorsFull,
      disabledReason: isLeader ? "Ти вже лідер" : isAdvisor ? "Ти вже радник" : "У раді вже достатньо радників",
    },
    {
      id: "rebel",
      label: "Повстанець",
      icon: Flame,
      desc: "Особлива роль серед звичайних громадян. Можливості з'являться пізніше.",
      disabled: me.role === "rebel",
      disabledReason: "Ти вже повстанець",
    },
  ];

  return (
    <div className="cn-shop-card" style={{ padding: 14 }}>
      <div className="cn-control-hint" style={{ marginBottom: 10 }}>
        Влада: купи роль у своїй країні за {fmt(ROLE_PRICE)} Power
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {roles.map((r) => {
          const Icon = r.icon;
          const blocked = r.disabled || !canAfford;
          return (
            <div key={r.id} className="cn-region-country-row" style={{ flexDirection: "column", alignItems: "stretch", gap: 6 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <Icon size={18} />
                <span className="cn-region-country-name">{r.label}</span>
                <span style={{ marginLeft: "auto", fontSize: 13, opacity: 0.8 }}>{fmt(ROLE_PRICE)} Power</span>
              </div>
              <div style={{ fontSize: 12, opacity: 0.7 }}>{r.desc}</div>
              <button className="cn-dev-btn" type="button" disabled={blocked || busyRole === r.id} onClick={() => buy(r.id)}>
                {busyRole === r.id ? "…" : r.disabled ? r.disabledReason : !canAfford ? "Недостатньо Power" : "Купити"}
              </button>
            </div>
          );
        })}
      </div>
      {msg && <div className="cn-dev-status-msg" style={{ marginTop: 8 }}>{msg}</div>}
    </div>
  );
}

function PremiumPassModal({ onClose, me, onSetPlayer, onGoToSeason }) {
  const perks = [
    {
      icon: Gift,
      title: "ПОДВІЙНІ НАГОРОДИ",
      desc: "Отримуй в 2 рази більше сили за рівні Battle Pass!",
    },
    {
      icon: Crown,
      title: "ЕКСКЛЮЗИВНІ ТИТУЛИ",
      desc: "Виділяйся серед інших гравців унікальними титулами!",
    },
    {
      icon: ShieldCheck,
      title: "ЕКСКЛЮЗИВНІ ЗНАЧКИ",
      desc: "Покажи свій статус за допомогою особливих значків!",
    },
    {
      icon: User,
      title: "ЕКСКЛЮЗИВНІ ІКОНКИ ПРОФІЛЮ",
      desc: "Унікальні іконки для твого профілю!",
    },
  ];

  const owned = !!me?.hasPremiumPass;
  const close = () => { cnSfx.modalClose(); onClose(); };

  const handleBuy = async () => {
    if (!me || owned) return;
    const paid = await buyPremiumPass(me, onSetPlayer);
    if (!paid) return;
    cnSfx.purchase();
    onClose();
    if (onGoToSeason) onGoToSeason();
  };

  return (
    <div className="cn-modal-overlay" onClick={close}>
      <div className="cn-modal-sheet cn-premium-modal" onClick={(e) => e.stopPropagation()}>
        <div className="cn-premium-hero">
          <img className="cn-premium-hero-img" src={SHOP_BANNER_IMG} alt="Premium Pass" />
          <button className="cn-icon-btn cn-premium-close" type="button" onClick={close} aria-label="Закрити">
            <X size={16} />
          </button>
        </div>

        <div className="cn-premium-perks-title">
          <span className="cn-premium-perks-line" />
          ТИ ОТРИМУЄШ
          <span className="cn-premium-perks-line" />
        </div>

        <div className="cn-premium-perks">
          {perks.map((p) => (
            <div className="cn-premium-perk" key={p.title}>
              <div className="cn-premium-perk-icon">
                <p.icon size={20} />
              </div>
              <div>
                <div className="cn-premium-perk-title">{p.title}</div>
                <div className="cn-premium-perk-desc">{p.desc}</div>
              </div>
            </div>
          ))}
        </div>

        <button
          className="cn-shop-more-btn cn-premium-buy-btn"
          type="button"
          disabled={owned}
          onClick={handleBuy}
        >
          <Crown size={16} /> {owned ? "Вже придбано" : "Активувати Premium Pass"}
        </button>
      </div>
    </div>
  );
}

function ComingSoon({ title, description, icon: Icon }) {

  return (
    <div className="cn-soon">
      <div className="cn-soon-icon-wrap">
        <Icon size={30} className="cn-soon-icon" />
        <div className="cn-soon-lock">
          <Lock size={12} />
        </div>
      </div>
      <div className="cn-soon-title">{title}</div>
      <div className="cn-soon-badge">Coming Soon</div>
      <div className="cn-soon-desc">{description}</div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Bottom navigation                                                   */
/* ------------------------------------------------------------------ */

function BottomNav({ tab, setTab, unreadMail, lang = "uk" }) {
  return (
    <nav className="cn-nav">
      {NAV.map((item) => {
        const Icon = item.icon;
        const active = tab === item.id;
        return (
          <button
            key={item.id}
            className={"cn-nav-btn" + (active ? " cn-nav-btn--active" : "")}
            onClick={() => {
              if (item.id !== tab) cnSfx.navSwitch();
              setTab(item.id);
            }}
            type="button"
          >
            <div className="cn-nav-icon-wrap">
              <Icon size={22} />
              {item.soon && <span className="cn-nav-dot" />}
              {item.id === "profile" && unreadMail > 0 && (
                <span className="cn-nav-badge">{unreadMail > 9 ? "9+" : unreadMail}</span>
              )}
            </div>
            <span className="cn-nav-label">{t(lang, "nav_" + item.id)}</span>
          </button>
        );
      })}
    </nav>
  );
}

